UPDATE senate_races SET candidate2_name = 'Mike Collins', candidate2_party = 'R' WHERE state_code = 'GA';

-- Fix OR Senate: clear the write-in glitch from candidate1 (AP feed artifact)
UPDATE senate_races SET candidate1_name = NULL, candidate1_party = NULL WHERE state_code = 'OR' AND candidate1_name = 'Total Write-ins';

-- Fix AL-5 duplicate: Dale Strong is uncontested, clear the duplicate
UPDATE house_races SET candidate2_name = NULL, candidate2_party = NULL WHERE state_code = 'AL' AND district = 5 AND candidate2_name LIKE '%Dale%Strong%';

